import React from "react";
import { useCurrentFrame, useVideoConfig, AbsoluteFill, interpolate, random } from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map(f => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700;800`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type SpaceWarpProps = Record<string, any>;

const SpaceWarp: React.FC<SpaceWarpProps> = ({
  backgroundColor = "#030208",
  transparentBackground = false,
  durationInSeconds = 10,
  coreGlowColor = "#15122b",
  streakColors = [
    "#ffffff", // White
    "#22c55e", // Neon Green
    "#06b6d4", // Cyan
    "#a855f7", // Purple
    "#eab308", // Yellow
    "#6b7280", // Dim Grey
  ],
  particleCount = 1500,
  travelSpeed = 12.5,
  tailLength = 200,
  fieldOfView = 1200,
  centerText = "Malloy Studio",
  titleFont = "Caveat",
  companyLogo = "https://malloy-files-c0ddahgefecthmcs.z03.azurefd.net/web/template_assets/logos/logoanimation(round).png",
  logoSize = 250,
}) => {
  useFontLoader(["Inter", titleFont]);

  const frame = useCurrentFrame();
  const { width, height } = useVideoConfig();

  // Screen center coordinates
  const cx = width / 2;
  const cy = height / 2;
  
  // Maximum depth before a particle resets to the "back" of the field
  const MAX_DEPTH = 2500;

  // Generate a stable field of particles with random 3D origins
  const particles = React.useMemo(() => {
    return new Array(particleCount).fill(0).map((_, i) => {
      const seed = `particle-${i}`;
      
      // Expand the x/y generation bounds to ensure particles fill the 16:9 edges
      // when they get close to the camera, rather than creating a visible tunnel edge.
      const spreadX = width * 2.5;
      const spreadY = height * 2.5;

      return {
        id: i,
        // Original Cartesian coordinates in space
        x: (random(seed + "x") - 0.5) * spreadX,
        y: (random(seed + "y") - 0.5) * spreadY,
        // Stagger their initial placement along the Z axis
        zOffset: random(seed + "z") * MAX_DEPTH,
        // Assign a random color from the palette
        color: streakColors[Math.floor(random(seed + "color") * streakColors.length)],
        // Vary thickness slightly for depth illusion
        thickness: random(seed + "thick") * 1.5 + 0.5,
      };
    });
  }, [particleCount, width, height, streakColors]);

  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;

  // Intro animation for center elements
  const centerOpacity = interpolate(frame, [0, 20], [0, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });
  const centerScale = interpolate(frame, [0, 40], [0.9, 1], {
    extrapolateLeft: "clamp",
    extrapolateRight: "clamp",
  });

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor, fontFamily: "Inter" }}>
      
      {/* Subtle core nebula glow behind the stars */}
      {!transparentBackground && (
        <AbsoluteFill
          style={{
            background: `radial-gradient(ellipse at center, ${coreGlowColor} 0%, transparent 60%)`,
            opacity: 0.85,
            transition: "none",
          }}
        />
      )}

      {/* Render the 3D projected streaks as an SVG layer */}
      <svg 
        style={{ 
          width: "100%", 
          height: "100%", 
          overflow: "hidden", 
          transition: "none",
          position: "absolute",
          top: 0,
          left: 0,
        }}
      >
        {particles.map((particle) => {
          // Calculate how far this particle has traveled globally
          const distanceTraveled = frame * travelSpeed * 2.5 + particle.zOffset;

          // Wrap the Z coordinate so particles loop from back to front continuously.
          // Z = MAX_DEPTH is far away, Z = 0 is right at the camera lens.
          const headZ = MAX_DEPTH - (distanceTraveled % MAX_DEPTH);

          // Avoid division by zero or extreme glitching right behind the camera
          if (headZ < 1) return null;

          // The tail trails behind the head in 3D space (higher Z value)
          const tailZ = headZ + tailLength;

          // 3D to 2D Perspective Projection Equations
          // Screen X = (WorldX / WorldZ) * FOV + CenterX
          const headScreenX = (particle.x / headZ) * fieldOfView + cx;
          const headScreenY = (particle.y / headZ) * fieldOfView + cy;

          const tailScreenX = (particle.x / tailZ) * fieldOfView + cx;
          const tailScreenY = (particle.y / tailZ) * fieldOfView + cy;

          // Opacity Control:
          // - Fade out slightly right before passing the camera (Z: 10 to 50)
          // - Full brightness in the mid-ground (Z: 50 to MAX_DEPTH * 0.7)
          // - Fade in smoothly from the far distance (Z: MAX_DEPTH * 0.7 to MAX_DEPTH)
          const opacity = interpolate(
            headZ,
            [10, 50, MAX_DEPTH * 0.7, MAX_DEPTH],
            [0.2, 1, 1, 0],
            { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
          );

          // Performance Optimization: Culling
          // If both the head and tail are far off-screen, don't render the SVG node.
          const renderMargin = 150;
          const isOffScreen =
            (headScreenX < -renderMargin && tailScreenX < -renderMargin) ||
            (headScreenX > width + renderMargin && tailScreenX > width + renderMargin) ||
            (headScreenY < -renderMargin && tailScreenY < -renderMargin) ||
            (headScreenY > height + renderMargin && tailScreenY > height + renderMargin);

          if (isOffScreen) return null;

          return (
            <line
              key={particle.id}
              x1={tailScreenX}
              y1={tailScreenY}
              x2={headScreenX}
              y2={headScreenY}
              stroke={particle.color}
              strokeWidth={particle.thickness}
              strokeLinecap="round"
              opacity={opacity}
              style={{ transition: "none" }}
            />
          );
        })}
      </svg>

      {/* Foreground Content: Center Text & Company Logo */}
      <AbsoluteFill
        style={{
          justifyContent: "center",
          alignItems: "center",
          flexDirection: "column",
          gap: "40px",
          zIndex: 10,
          opacity: centerOpacity,
          transform: `scale(${centerScale})`,
          transition: "none",
        }}
      >
        {companyLogo && (
          <img
            src={companyLogo}
            alt="Company Logo"
            style={{ 
              width: logoSize, 
              height: logoSize, 
              objectFit: "contain",
              filter: "drop-shadow(0px 0px 40px rgba(255, 255, 255, 0.2))",
            }}
          />
        )}
        {centerText && (
          <h1
            style={{
              color: "#ffffff",
              fontFamily: titleFont,
              fontSize: "120px",
              fontWeight: 800,
              margin: 0,
              textAlign: "center",
              maxWidth: width * 0.8,
              lineHeight: 1.1,
              letterSpacing: "-0.02em",
              textShadow: "0 8px 30px rgba(0,0,0,0.8), 0 0 40px rgba(255,255,255,0.3)",
            }}
          >
            {centerText}
          </h1>
        )}
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default SpaceWarp;